  { json: { raw_name: 'Dr. John van der Sar' } },
  { json: { raw_name: 'Pedro123 Gomez' } },
  { json: { raw_name: 'Al' } },
  { json: { raw_name: '' } }
];

// ==========================================================================
// Immersive Office - Normalizador y Validador Avanzado de Nombres
// ==========================================================================
const items = $input.all();
const results = [];

// Palabras que deben permanecer en minúscula si van en medio (preposiciones/artículos)
const lowerWords = new Set(['de', 'del', 'la', 'las', 'los', 'y', 'e', 'van', 'von', 'da', 'di', 'der']);

for (const item of items) {
  // Extraer nombre de múltiples fuentes posibles (mock data, body o query)
  const inputName = item.json.raw_name || item.json.body?.name || item.json.body?.nombre || item.json.query?.name || item.json.query?.nombre || item.json.name || "";

  let raw = String(inputName).trim();
  let isValid = false;
  let errors = [];
  let normalizedName = "";
  let parts = [];
  let firstName = "";
  let lastName = "";

  if (!raw || raw.length === 0) {
    errors.push("El nombre no puede estar vacío.");
  } else if (raw.length < 3) {
    errors.push("El nombre debe tener al menos 3 caracteres.");
  } else if (/[0-9]/.test(raw)) {
    errors.push("El nombre no puede contener números.");
  } else if (/[@#$%^&*()_+=\[\]{};:"\\|<>/]/.test(raw)) {
    errors.push("El nombre contiene caracteres especiales no permitidos.");
  } else {
    // Limpiar espacios múltiples
    const cleaned = raw.replace(/\s+/g, ' ');
    const words = cleaned.toLowerCase().split(' ');

    // Capitalizar adecuadamente (Title Case considerando excepciones de partículas)
    const capitalizedWords = words.map((w, index) => {
      if (index > 0 && lowerWords.has(w)) {
        return w;
      }
      return w.charAt(0).toUpperCase() + w.slice(1);
    });

    normalizedName = capitalizedWords.join(' ');
    parts = capitalizedWords;

    // Segmentar Nombre y Apellidos (heurística española/latina estándar)
    if (parts.length === 1) {
      firstName = parts[0];
      lastName = "";
    } else if (parts.length === 2) {
      firstName = parts[0];
      lastName = parts[1];
    } else if (parts.length >= 3) {
      firstName = parts.slice(0, parts.length - 2).join(' ');
      lastName = parts.slice(parts.length - 2).join(' ');
    }

    isValid = true;
  }

  results.push({
    json: {
      input_original: raw,
      es_valido: isValid,
      nombre_normalizado: normalizedName,
      primer_nombre: firstName,
      apellidos: lastName,
      total_palabras: parts.length,
      errores: errors,
      procesado_el: new Date().toISOString(),
      fuente: "immersiveoffice.online"
    }
  });
}

return results;
